setups.app_0007:
-- Harbourline Recon migration 0007: the import as one function (one call = one transaction)
BEGIN;
CREATE FUNCTION import_statement(p_insurer_id integer, p_statement_month date, p_file_name text, p_rows jsonb)
RETURNS jsonb
LANGUAGE plpgsql
AS $$
DECLARE
  v_hash     text;
  v_n        integer;
  v_batch    integer;
  v_inserted integer;
  v_bad      record;
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'The file has no rows to import';
  END IF;
  IF p_statement_month <> date_trunc('month', p_statement_month) THEN
    RAISE EXCEPTION 'Statement month must be the first day of a month, got %', p_statement_month;
  END IF;

  -- Validate every row before inserting anything, and name the first bad row.
  SELECT e.ord, e.r INTO v_bad
  FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS e (r, ord)
  WHERE coalesce(e.r ->> 'booking_date', '') !~ '^\d{2}-\d{2}-\d{4}$'
     OR coalesce(e.r ->> 'amount', '') !~ '^-?[0-9.]*[0-9](,[0-9]{1,2})?$'
     OR coalesce(e.r ->> 'commission', '') !~ '^-?[0-9.]*[0-9](,[0-9]{1,2})?$'
     OR coalesce(e.r ->> 'line_type', '') NOT IN ('premium', 'correction', 'cancellation_refund')
     OR coalesce(trim(e.r ->> 'policy_number'), '') = ''
  ORDER BY e.ord LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'Row %: unexpected value in %', v_bad.ord, v_bad.r;
  END IF;

  -- Content hash, computed the same way as the promote statement of Module 7.
  SELECT encode(sha256(convert_to(string_agg(concat_ws(',', e.r ->> 'policy_number', e.r ->> 'invoice_reference', e.r ->> 'booking_date',
                                                  e.r ->> 'amount', e.r ->> 'commission', e.r ->> 'line_type'), E'\n' ORDER BY e.ord), 'UTF8')), 'hex'),
         count(*)
    INTO v_hash, v_n
  FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS e (r, ord);

  INSERT INTO import_batches (insurer_id, statement_month, file_name, file_sha256, row_count)
  VALUES (p_insurer_id, p_statement_month, p_file_name, v_hash, v_n)
  ON CONFLICT (file_sha256) DO NOTHING
  RETURNING batch_id INTO v_batch;

  IF v_batch IS NULL THEN
    RETURN jsonb_build_object('status', 'duplicate', 'file_sha256', v_hash,
      'existing_batch_id', (SELECT batch_id FROM import_batches WHERE file_sha256 = v_hash));
  END IF;

  INSERT INTO statement_lines (batch_id, source_row, policy_number_raw, invoice_reference, booking_date, amount, commission, line_type)
  SELECT v_batch, e.ord, trim(e.r ->> 'policy_number'), nullif(trim(e.r ->> 'invoice_reference'), ''),
         to_date(e.r ->> 'booking_date', 'DD-MM-YYYY'),
         replace(replace(e.r ->> 'amount', '.', ''), ',', '.')::numeric(12,2),
         replace(replace(e.r ->> 'commission', '.', ''), ',', '.')::numeric(12,2),
         e.r ->> 'line_type'
  FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS e (r, ord);
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted <> v_n THEN
    RAISE EXCEPTION 'Inserted % lines, expected %', v_inserted, v_n;
  END IF;

  RETURN jsonb_build_object('status', 'imported', 'batch_id', v_batch, 'rows', v_inserted,
    'outside_month', (SELECT count(*) FROM statement_lines
                      WHERE batch_id = v_batch AND date_trunc('month', booking_date)::date <> p_statement_month));
END;
$$;
REVOKE EXECUTE ON FUNCTION import_statement(integer, date, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION import_statement(integer, date, text, jsonb) TO authenticated;
INSERT INTO schema_migrations (version) VALUES ('0007_import_function');
COMMIT;

