setups.perf_big:
-- Module 13: two larger tables to make query plans visible (generated, deterministic).
CREATE TABLE big_lines AS
SELECT g AS line_id,
       1 + (g % 6) AS insurer_id,
       'POL' || lpad(((g * 7919) % 40000)::text, 6, '0') AS policy_key,
       (date '2023-01-01' + make_interval(months => g % 40))::date AS month,
       round(((g * 37) % 100000) / 100.0, 2)::numeric(12,2) AS amount,
       CASE WHEN g % 3 = 0 THEN NULL ELSE 'INV-' || lpad(g::text, 6, '0') END AS invoice_reference
FROM generate_series(1, 100000) AS g;
ALTER TABLE big_lines ADD PRIMARY KEY (line_id);
CREATE TABLE big_reviews AS
SELECT g AS review_id,
       'line:' || ((g * 13) % 100000 + 1) AS exception_key,
       timestamptz '2025-01-01 00:00+00' + make_interval(mins => g) AS reviewed_at,
       CASE g % 5 WHEN 0 THEN 'needs_info' ELSE 'accepted' END AS decision,
       1 + g % 3 AS reviewed_by
FROM generate_series(1, 50000) AS g;
ALTER TABLE big_reviews ADD PRIMARY KEY (review_id);
ANALYZE big_lines;
ANALYZE big_reviews;
-- Course helpers: show a query's plan without costs, or test whether it contains a plan node.
-- (They run the text you pass on purpose; never build a function like this for an app.)
CREATE FUNCTION plan_of(q text) RETURNS SETOF text LANGUAGE plpgsql AS $$
DECLARE r record;
BEGIN
  FOR r IN EXECUTE 'EXPLAIN (COSTS OFF) ' || q LOOP RETURN NEXT r."QUERY PLAN"; END LOOP;
END $$;
CREATE FUNCTION plan_uses(q text, node text) RETURNS boolean LANGUAGE sql AS $$
  SELECT EXISTS (SELECT 1 FROM plan_of(q) AS p WHERE p LIKE '%' || node || '%')
$$;

