files.app_csv:
// Minimal CSV reader for insurer statements: comma separated, fields may be "quoted",
// quotes inside a quoted field are doubled (""). Values stay TEXT: converting Dutch dates
// and decimal commas happens in SQL (import_statement), in one place.

export type RawRow = Record<string, string>;

export function parseCsv(text: string): RawRow[] {
  const records: string[][] = [];
  let field = '', record: string[] = [], quoted = false;
  const src = text.replace(/^﻿/, '');            // drop a byte-order mark
  for (let i = 0; i < src.length; i++) {
    const ch = src[i];
    if (quoted) {
      if (ch === '"' && src[i + 1] === '"') { field += '"'; i++; }
      else if (ch === '"') quoted = false;
      else field += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { record.push(field); field = ''; }
    else if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && src[i + 1] === '\n') i++;
      record.push(field); field = '';
      if (record.some(v => v !== '')) records.push(record);
      record = [];
    } else field += ch;
  }
  record.push(field);
  if (record.some(v => v !== '')) records.push(record);

  const [header, ...rows] = records;
  if (!header) return [];
  const names = header.map(h => h.trim());
  return rows.map((r, n) => {
    if (r.length !== names.length) throw new Error(`Line ${n + 2} has ${r.length} fields, expected ${names.length}`);
    return Object.fromEntries(names.map((name, k) => [name, r[k]]));
  });
}

