import type { RawRow } from './csv';

export const supabase = createClient(
  import.meta.env.VITE_SUPABASE_URL,
  import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY
);

function fail(what: string, error: { message: string }): never {
  throw new Error(`${what}: ${error.message}`);
}

export type Staff = { staff_id: number; full_name: string; role: 'team_lead' | 'reconciler' | 'viewer' };
export type Insurer = { insurer_id: number; code: string; name: string };
export type SummaryRow = { insurer_id: number; month: string; exceptions: number; missing: number; not_ours: number; ambiguous: number; differences: number; timing: number; duplicates: number };
export type ExceptionRow = { exception_key: string; kind: string; insurer_id: number; month: string; invoice_id: number | null; line_id: number | null; our_amount: number | null; their_amount: number | null; difference: number | null; evidence: string };
export type Review = { exception_key: string; decision: string; note: string | null; reviewed_by: number; reviewed_at: string };
export type Filters = { insurer_id?: number; month?: string; kinds?: string[] };
export type SavedView = { view_id: number; name: string; filters: Filters; version: number };

export const DECISIONS = ['accepted', 'to_insurer', 'to_finance', 'corrected_in_books', 'needs_info'] as const;

export async function signIn(email: string, password: string) {
  const { error } = await supabase.auth.signInWithPassword({ email, password });
  if (error) fail('Sign-in failed', error);
}
export async function signOut() { await supabase.auth.signOut(); }

export async function getMe(): Promise<Staff | null> {
  const { data: auth } = await supabase.auth.getUser();
  if (!auth.user) return null;
  const { data, error } = await supabase.from('staff').select('staff_id, full_name, role').eq('user_id', auth.user.id).maybeSingle();
  if (error) fail('Loading your staff record', error);
  return data;
}

export async function getInsurers(): Promise<Insurer[]> {
  const { data, error } = await supabase.from('insurers').select('insurer_id, code, name').order('code');
  if (error) fail('Loading insurers', error);
  return data;
}

export async function getSummary(month?: string): Promise<SummaryRow[]> {
  let q = supabase.from('recon_summary').select('*').order('month').order('insurer_id');
  if (month) q = q.eq('month', month);
  const { data, error } = await q;
  if (error) fail('Loading the summary', error);
  return data;
}

export async function getExceptions(f: Filters): Promise<ExceptionRow[]> {
  let q = supabase.from('recon_exceptions').select('*').order('exception_key').limit(500);
  if (f.insurer_id) q = q.eq('insurer_id', f.insurer_id);
  if (f.month) q = q.eq('month', f.month);
  if (f.kinds && f.kinds.length) q = q.in('kind', f.kinds);
  const { data, error } = await q;
  if (error) fail('Loading exceptions', error);
  return data;
}

export async function getCurrentReviews(keys: string[]): Promise<Map<string, Review>> {
  if (!keys.length) return new Map();
  const { data, error } = await supabase.from('exception_current_review').select('*').in('exception_key', keys);
  if (error) fail('Loading decisions', error);
  return new Map((data as Review[]).map(r => [r.exception_key, r]));
}

export async function getHistory(key: string): Promise<Review[]> {
  const { data, error } = await supabase.from('exception_reviews').select('exception_key, decision, note, reviewed_by, reviewed_at')
    .eq('exception_key', key).order('reviewed_at');
  if (error) fail('Loading the history', error);
  return data;
}

export async function addReview(me: Staff, key: string, decision: string, note: string) {
  const { error } = await supabase.from('exception_reviews')
    .insert({ exception_key: key, decision, note: note.trim() || null, reviewed_by: me.staff_id });
  if (error) fail('Saving the decision', error);
}

export async function getSavedViews(): Promise<SavedView[]> {
  const { data, error } = await supabase.from('saved_views').select('view_id, name, filters, version').order('name');
  if (error) fail('Loading saved views', error);
  return data;
}

export async function saveView(name: string, filters: Filters) {
  const { data: auth } = await supabase.auth.getUser();
  const { error } = await supabase.from('saved_views').insert({ owner_id: auth.user?.id, name, filters });
  if (error) fail('Saving the view', error);
}

// Optimistic check: only update when nobody changed the view since we read it.
export async function updateView(v: SavedView, filters: Filters): Promise<'saved' | 'changed elsewhere'> {
  const { data, error } = await supabase.from('saved_views')
    .update({ filters, version: v.version + 1 })
    .eq('view_id', v.view_id).eq('version', v.version)
    .select('view_id');
  if (error) fail('Updating the view', error);
  return data.length === 1 ? 'saved' : 'changed elsewhere';
}

export type ImportResult = { status: 'imported'; batch_id: number; rows: number; outside_month: number } | { status: 'duplicate'; existing_batch_id: number };

export async function importStatement(insurerId: number, month: string, fileName: string, rows: RawRow[]): Promise<ImportResult> {
  const { data, error } = await supabase.rpc('import_statement', {
    p_insurer_id: insurerId, p_statement_month: month, p_file_name: fileName, p_rows: rows
  });
  if (error) fail('Import refused', error);
  return data as ImportResult;
}

