// Screens of Harbourline Recon. This file only draws and reacts; every database call is in db.ts.
import * as db from './db';
import { parseCsv } from './csv';

const app = document.querySelector<HTMLDivElement>('#app')!;
const eur = new Intl.NumberFormat('nl-NL', { style: 'currency', currency: 'EUR' });

// Never put database text into the page as HTML without escaping it.
function esc(v: unknown): string {
  return String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]!));
}
function money(v: number | null): string { return v === null ? '' : eur.format(v); }
function show(el: HTMLElement, text: string, kind: 'ok' | 'err') { el.innerHTML = `<div class="msg ${kind}">${esc(text)}</div>`; }

type State = { me: db.Staff; insurers: db.Insurer[]; filters: db.Filters; selected: string | null; views: db.SavedView[] };
let state: State;

async function start() {
  const me = await db.getMe().catch(() => null);
  if (!me) return drawSignIn();
  state = { me, insurers: await db.getInsurers(), filters: { month: '2026-01-01' }, selected: null, views: await db.getSavedViews() };
  drawShell();
  await refresh();
}

function drawSignIn() {
  app.innerHTML = `<main><section><h2>Sign in</h2>
    <form id="login"><label>Email <input name="email" type="email" required></label>
    <label>Password <input name="password" type="password" required></label>
    <button class="primary">Sign in</button></form><div id="loginMsg"></div>
    <p class="muted">Only team members with a staff record can use this app.</p></section></main>`;
  document.querySelector<HTMLFormElement>('#login')!.addEventListener('submit', async ev => {
    ev.preventDefault();
    const f = new FormData(ev.currentTarget as HTMLFormElement);
    try { await db.signIn(String(f.get('email')), String(f.get('password'))); await start(); }
    catch (e) { show(document.querySelector('#loginMsg')!, (e as Error).message, 'err'); }
  });
}

function drawShell() {
  const ins = state.insurers.map(i => `<option value="${i.insurer_id}">${esc(i.code)} · ${esc(i.name)}</option>`).join('');
  app.innerHTML = `
  <header><h1>Harbourline Recon</h1><div class="row"><span class="muted">${esc(state.me.full_name)} · ${esc(state.me.role)}</span><button id="out">Sign out</button></div></header>
  <main>
    <section><h2>Summary</h2><div id="summary"></div></section>
    <section><h2>Exceptions</h2>
      <form id="filters">
        <label>Insurer <select name="insurer"><option value="">All</option>${ins}</select></label>
        <label>Month <input name="month" type="month" value="2026-01"></label>
        <label>Kinds <select name="kinds"><option value="">All kinds</option><option value="person">Needs a person</option><option value="diff">Differences</option></select></label>
        <button class="primary">Show</button>
        <label>Saved views <select id="views"><option value="">Choose…</option></select></label>
        <button type="button" id="saveView">Save as view</button>
      </form>
      <div id="list"></div>
    </section>
    <section id="detail"><h2>Decision</h2><p class="muted">Choose an exception in the list.</p></section>
    <section><h2>Import a statement</h2>
      <form id="import">
        <label>Insurer <select name="insurer" required>${ins}</select></label>
        <label>Statement month <input name="month" type="month" required></label>
        <label>CSV file <input name="file" type="file" accept=".csv,text/csv" required></label>
        <button class="primary">Import</button>
      </form><div id="importMsg"></div>
    </section>
  </main>`;
  document.querySelector('#out')!.addEventListener('click', async () => { await db.signOut(); drawSignIn(); });
  document.querySelector('#filters')!.addEventListener('submit', ev => { ev.preventDefault(); state.filters = readFilters(ev.currentTarget as HTMLFormElement); refresh(); });
  document.querySelector('#import')!.addEventListener('submit', onImport);
  document.querySelector('#saveView')!.addEventListener('click', onSaveView);
  document.querySelector('#views')!.addEventListener('change', ev => {
    const v = state.views.find(x => String(x.view_id) === (ev.target as HTMLSelectElement).value);
    if (v) { state.filters = v.filters; refresh(); }
  });
  drawViews();
}

const KIND_GROUPS: Record<string, string[]> = {
  person: ['ambiguous', 'not_in_our_books', 'missing_on_statement', 'amount_difference'],
  diff: ['amount_difference', 'rounding', 'commission_difference', 'timing_difference'],
};
function readFilters(form: HTMLFormElement): db.Filters {
  const f = new FormData(form);
  const out: db.Filters = {};
  if (f.get('insurer')) out.insurer_id = Number(f.get('insurer'));
  if (f.get('month')) out.month = String(f.get('month')) + '-01';
  if (f.get('kinds')) out.kinds = KIND_GROUPS[String(f.get('kinds'))];
  return out;
}

function drawViews() {
  const sel = document.querySelector<HTMLSelectElement>('#views')!;
  sel.innerHTML = '<option value="">Choose…</option>' + state.views.map(v => `<option value="${v.view_id}">${esc(v.name)}</option>`).join('');
}

async function onSaveView() {
  const name = prompt('Name for this view?');
  if (!name) return;
  try { await db.saveView(name, state.filters); state.views = await db.getSavedViews(); drawViews(); }
  catch (e) { alert((e as Error).message); }
}

async function refresh() {
  const sumEl = document.querySelector<HTMLDivElement>('#summary')!, listEl = document.querySelector<HTMLDivElement>('#list')!;
  try {
    const code = new Map(state.insurers.map(i => [i.insurer_id, i.code]));
    const summary = await db.getSummary(state.filters.month);
    sumEl.innerHTML = summary.length ? `<table><tr><th>Insurer</th><th>Month</th><th>Exceptions</th><th>Missing</th><th>Not ours</th><th>Ambiguous</th><th>Differences</th><th>Timing</th><th>Duplicates</th></tr>
      ${summary.map(s => `<tr><td>${esc(code.get(s.insurer_id))}</td><td>${esc(s.month)}</td>${[s.exceptions, s.missing, s.not_ours, s.ambiguous, s.differences, s.timing, s.duplicates].map(n => `<td class="num">${n}</td>`).join('')}</tr>`).join('')}</table>`
      : '<p class="muted">No exceptions for this month.</p>';

    const rows = await db.getExceptions(state.filters);
    const reviews = await db.getCurrentReviews(rows.map(r => r.exception_key));
    listEl.innerHTML = rows.length ? `<table><tr><th>Kind</th><th>Insurer</th><th>Month</th><th>Ours</th><th>Theirs</th><th>Difference</th><th>Evidence</th><th>Decision</th></tr>
      ${rows.map(r => `<tr class="pick${r.exception_key === state.selected ? ' sel' : ''}" data-key="${esc(r.exception_key)}"><td>${esc(r.kind)}</td><td>${esc(code.get(r.insurer_id))}</td><td>${esc(r.month)}</td>
        <td class="num">${money(r.our_amount)}</td><td class="num">${money(r.their_amount)}</td><td class="num">${money(r.difference)}</td><td>${esc(r.evidence)}</td><td>${esc(reviews.get(r.exception_key)?.decision ?? 'open')}</td></tr>`).join('')}</table>
      <p class="muted">${rows.length} exceptions${rows.length === 500 ? ' (first 500 shown)' : ''}.</p>`
      : '<p class="muted">No exceptions match these filters.</p>';
    listEl.querySelectorAll<HTMLTableRowElement>('tr.pick').forEach(tr => tr.addEventListener('click', () => { state.selected = tr.dataset.key!; drawDetail(); refreshSelection(); }));
  } catch (e) { show(listEl, (e as Error).message, 'err'); }
}
function refreshSelection() {
  document.querySelectorAll<HTMLTableRowElement>('tr.pick').forEach(tr => tr.classList.toggle('sel', tr.dataset.key === state.selected));
}

async function drawDetail() {
  const el = document.querySelector<HTMLElement>('#detail')!;
  const key = state.selected!;
  try {
    const history = await db.getHistory(key);
    const canDecide = state.me.role !== 'viewer';
    el.innerHTML = `<h2>Decision · ${esc(key)}</h2>
      ${history.length ? `<table><tr><th>When</th><th>Decision</th><th>Note</th><th>By (staff id)</th></tr>${history.map(h => `<tr><td>${esc(new Date(h.reviewed_at).toLocaleString('nl-NL', { timeZone: 'Europe/Amsterdam' }))}</td><td>${esc(h.decision)}</td><td>${esc(h.note)}</td><td>${h.reviewed_by}</td></tr>`).join('')}</table>` : '<p class="muted">No decisions yet.</p>'}
      ${canDecide ? `<form id="review"><label>Decision <select name="decision">${db.DECISIONS.map(d => `<option>${d}</option>`).join('')}</select></label>
        <label>Note <input name="note" size="40"></label><button class="primary">Record decision</button></form>` : '<p class="muted">Viewers can read decisions but not record them.</p>'}
      <div id="reviewMsg"></div>`;
    el.querySelector<HTMLFormElement>('#review')?.addEventListener('submit', async ev => {
      ev.preventDefault();
      const f = new FormData(ev.currentTarget as HTMLFormElement);
      try { await db.addReview(state.me, key, String(f.get('decision')), String(f.get('note') ?? '')); await drawDetail(); await refresh(); }
      catch (e) { show(el.querySelector('#reviewMsg')!, (e as Error).message, 'err'); }
    });
  } catch (e) { show(el, (e as Error).message, 'err'); }
}

async function onImport(ev: Event) {
  ev.preventDefault();
  const form = ev.currentTarget as HTMLFormElement, msg = document.querySelector<HTMLDivElement>('#importMsg')!;
  const f = new FormData(form);
  const file = f.get('file') as File;
  try {
    const rows = parseCsv(await file.text());
    const result = await db.importStatement(Number(f.get('insurer')), String(f.get('month')) + '-01', file.name, rows);
    if (result.status === 'duplicate') show(msg, `This file was already imported (batch ${result.existing_batch_id}). Nothing changed.`, 'ok');
    else show(msg, `Imported ${result.rows} lines as batch ${result.batch_id}.${result.outside_month ? ` Warning: ${result.outside_month} lines are booked outside the statement month.` : ''}`, 'ok');
    await refresh();
  } catch (e) { show(msg, (e as Error).message, 'err'); }
}

start();

