practical.solution:
WITH ours AS (
  SELECT p.insurer_id, i.period_start AS month, sum(i.amount) AS total
  FROM premium_invoices i JOIN policies p ON p.policy_id = i.policy_id WHERE i.status <> 'cancelled' GROUP BY 1, 2
), theirs AS (
  SELECT insurer_id, statement_month AS month, sum(amount) AS total FROM insurer_statements WHERE line_type = 'premium' GROUP BY 1, 2
), per_month AS (
  SELECT COALESCE(o.insurer_id, t.insurer_id) AS insurer_id, COALESCE(o.month, t.month) AS month,
         COALESCE(o.total, 0) AS ours, COALESCE(t.total, 0) AS theirs
  FROM ours o FULL OUTER JOIN theirs t ON t.insurer_id = o.insurer_id AND t.month = o.month)
SELECT insurer_id, month, ours, theirs, theirs - ours AS difference FROM per_month ORDER BY insurer_id, month;

