);
CREATE TABLE repair_decisions (      -- the mechanic's decision, append-only, separate from the report
  decision_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  report_id   integer NOT NULL REFERENCES damage_reports,
  repair_cost numeric(8,2) NOT NULL CHECK (repair_cost >= 0),
  decided_at  timestamptz NOT NULL DEFAULT now()
);
-- Calculated, not stored: rental days, amount due (days x daily_price + repair costs), late returns.
-- Recorded: rentals, returns, damage reports and the mechanic's decisions (with who/when).
