-- Terminal A                                   -- Terminal B
BEGIN;
UPDATE saved_views SET name = 'A was here'
 WHERE view_id = 1;
                                                BEGIN;
                                                UPDATE saved_views SET name = 'B was here'
                                                 WHERE view_id = 1;        -- waits...
COMMIT;                                         -- ...B continues now
                                                COMMIT;
SELECT name FROM saved_views WHERE view_id = 1; -- 'B was here'

exercises.solution:
-- A: BEGIN; UPDATE saved_views SET name = name WHERE view_id = 1;
-- B: BEGIN; UPDATE saved_views SET name = name WHERE view_id = 2;
-- A: UPDATE saved_views SET name = name WHERE view_id = 2;   -- waits for B
-- B: UPDATE saved_views SET name = name WHERE view_id = 1;   -- ERROR: deadlock detected (one side is cancelled)
-- The survivor continues after the other's transaction is rolled back.
-- Prevention: always lock rows in the same order (e.g. ORDER BY view_id ... FOR UPDATE), so nobody waits in a circle.

SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '30s';
SELECT current_setting('lock_timeout') AS lock_timeout, current_setting('statement_timeout') AS statement_timeout;

