CREATE TABLE exception_comments (
  comment_id    integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  exception_key text NOT NULL,
  body          text NOT NULL,
  author_id     integer NOT NULL DEFAULT current_staff_id() REFERENCES staff (staff_id),
  created_at    timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, DELETE ON exception_comments TO authenticated;
ALTER TABLE exception_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_read ON exception_comments FOR SELECT TO authenticated USING ((SELECT current_staff_role()) IS NOT NULL);
CREATE POLICY staff_insert_own ON exception_comments FOR INSERT TO authenticated WITH CHECK ((SELECT current_staff_role()) IS NOT NULL AND author_id = (SELECT current_staff_id()));
CREATE POLICY delete_own ON exception_comments FOR DELETE TO authenticated USING (author_id = (SELECT current_staff_id()));
