let calls = 0;
const keys = ['missing:82:-', 'amount:80:287', 'rounding:6:343', 'ambiguous:-:125', 'missing:89:-'];
for (const k of keys) { calls++; await supabase.from('exception_current_review').select('decision').eq('exception_key', k).maybeSingle(); }
console.log('N+1:', calls, 'calls');
calls = 1;
const { data } = await supabase.from('exception_current_review').select('exception_key, decision').in('exception_key', keys);
console.log('one query:', calls, 'call,', data.length, 'decisions found');

